def integer_sqrt_floor(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    lo, hi = 0, n // 2 + 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

