def min_pages_per_reading_day(chapter_pages: List[int], days: int) -> int:
    if not chapter_pages:
        return 0

    def days_needed(limit: int) -> int:
        used, current = 1, 0
        for p in chapter_pages:
            if current + p > limit:
                used += 1
                current = 0
            current += p
        return used

    lo, hi = max(chapter_pages), sum(chapter_pages)
    while lo < hi:
        mid = (lo + hi) // 2
        if days_needed(mid) <= days:
            hi = mid
        else:
            lo = mid + 1
    return lo

