def smallest_divisor_within_budget(nums: List[int], budget: int) -> int:
    if not nums:
        return 1

    def cost(d: int) -> int:
        return sum((x + d - 1) // d for x in nums)

    lo, hi = 1, max(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if cost(mid) <= budget:
            hi = mid
        else:
            lo = mid + 1
    return lo

