def natural_sort_filenames(names: List[str]) -> List[str]:
    def key(name: str):
        parts = re.split(r"(\d+)", name)
        # Even indices are text, odd indices are digit runs.
        chunks = tuple((0, int(p), "") if i % 2 else (1, 0, p.casefold())
                       for i, p in enumerate(parts))
        return (chunks, name)

    return sorted(names, key=key)

