def count_at_most_in_sorted_grid(grid: List[List[int]], x: int) -> int:
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    r, c = rows - 1, 0
    count = 0
    while r >= 0 and c < cols:
        if grid[r][c] <= x:
            count += r + 1
            c += 1
        else:
            r -= 1
    return count

