def widest_minimum_gap_placement(spots: List[int], count: int) -> int:
    pos = sorted(spots)

    def fits(gap: int) -> bool:
        placed, last = 1, pos[0]
        for p in pos[1:]:
            if p - last >= gap:
                placed += 1
                last = p
                if placed >= count:
                    return True
        return placed >= count

    lo, hi = 0, pos[-1] - pos[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if fits(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

