def min_swaps_to_sort_distinct(nums: List[int]) -> int:
    target = {v: i for i, v in enumerate(sorted(nums))}
    visited = [False] * len(nums)
    swaps = 0
    for start in range(len(nums)):
        length = 0
        i = start
        while not visited[i]:
            visited[i] = True
            i = target[nums[i]]
            length += 1
        if length > 1:
            swaps += length - 1
    return swaps

